SELECT 
FROM gt_risk_monitoring
WHERE org_id = #{orgId}

    AND monitoring_no LIKE CONCAT('%', #{monitoringNo}, '%')


    AND risk_type_id = #{riskTypeId}


    AND business_unit = #{businessUnit}


    AND monitoring_status = #{monitoringStatus}


    AND risk_level = #{riskLevel}


    AND monitoring_date >= #{monitoringDateStart}


    AND monitoring_date <= #{monitoringDateEnd}

ORDER BY monitoring_date DESC, create_time DESC

SELECT 
FROM gt_risk_monitoring
WHERE monitoring_no = #{monitoringNo} AND org_id = #{orgId}

SELECT 
FROM gt_risk_monitoring
WHERE risk_type_id = #{riskTypeId} 

    AND org_id = #{orgId}

ORDER BY monitoring_date DESC

SELECT AVG(current_value)
FROM gt_risk_monitoring
WHERE org_id = #{orgId} 
AND monitoring_status = #{monitoringStatus}
AND current_value IS NOT NULL

SELECT MAX(current_value)
FROM gt_risk_monitoring
WHERE org_id = #{orgId} 
AND monitoring_status = #{monitoringStatus}
AND current_value IS NOT NULL

SELECT MIN(current_value)
FROM gt_risk_monitoring
WHERE org_id = #{orgId} 
AND monitoring_status = #{monitoringStatus}
AND current_value IS NOT NULL

SELECT COUNT(*)
FROM gt_risk_monitoring
WHERE monitoring_no = #{monitoringNo} AND org_id = #{orgId}

    AND monitoring_id != #{excludeId}
